class DesktopDocumentIndexTransactionInspectorTest {
    // Independent, frozen raw-byte oracle. Never generated by JWire/Inspector or prepare().
    private val goldenResource="/g2-a-j-v1-golden/"
    private val goldenBundle="entities/document_index_transactions/history/66666666-6666-4666-8666-666666666666"
    private fun goldenBytes(name:String)=requireNotNull(javaClass.getResourceAsStream(goldenResource+name)).use{it.readBytes()}
    private fun goldenManifest():JsonObject {
        val raw=goldenBytes("manifest.json")
        assertEquals("b4afa563dc58b9830188d0d8d76b1d08a42259cfba795aacebaa2d4d8ad09bde",DesktopDocumentIndexTransactionSyntheticFixture.hash(raw))
        return Json.parseToJsonElement(raw.toString(Charsets.UTF_8)).jsonObject
    }
    private fun installGolden(f:DesktopDocumentIndexTransactionSyntheticFixture) {
        val manifest=goldenManifest()
        for(entry in manifest.getValue("directories").jsonArray)Files.createDirectories(f.root.resolve(entry.jsonPrimitive.content))
        for(entry in manifest.getValue("files").jsonArray) {
            val path=entry.jsonObject.getValue("path").jsonPrimitive.content
            f.write(f.root.resolve(path),goldenBytes("root/$path"))
        }
        assertGoldenBytes(f)
    }
    private fun assertGoldenBytes(f:DesktopDocumentIndexTransactionSyntheticFixture) {
        val manifest=goldenManifest()
        val expected=manifest.getValue("files").jsonArray.map{it.jsonObject}
        assertEquals(18,expected.size)
        val files=Files.walk(f.root).use{paths->paths.filter{Files.isRegularFile(it) && it!=f.owner.lockPath}.toList()}
        assertEquals(expected.map{it.getValue("path").jsonPrimitive.content}.toSet(),files.map{f.root.relativize(it).toString().replace('\\','/')}.toSet())
        val directories=Files.walk(f.root).use{paths->paths.filter{Files.isDirectory(it)}.map{f.root.relativize(it).toString().replace('\\','/')}.toList().toSet()}
        assertEquals(manifest.getValue("directories").jsonArray.map{it.jsonPrimitive.content}.toSet(),directories)
        for(entry in expected) {
            val path=entry.getValue("path").jsonPrimitive.content
            val raw=Files.readAllBytes(f.root.resolve(path))
            assertEquals(entry.getValue("bytes").jsonPrimitive.long,raw.size.toLong(),path)
            assertEquals(entry.getValue("sha256").jsonPrimitive.content,DesktopDocumentIndexTransactionSyntheticFixture.hash(raw),path)
        }
    }
    @Test fun `independent complete golden pins every raw file control field and JSONL order`()=runBlocking<Unit> {
        DesktopDocumentIndexTransactionSyntheticFixture().use{f->
            installGolden(f)
            val manifest=goldenManifest()
            for((path,kind) in manifest.getValue("controlKinds").jsonObject) {
                val control=Json.parseToJsonElement(Files.readString(f.root.resolve(path))).jsonObject
                assertEquals("CCB_DOCUMENT_INDEX_J",control.getValue("format").jsonPrimitive.content)
                assertEquals(1,control.getValue("version").jsonPrimitive.int)
                assertEquals(kind,control.getValue("kind"))
                if(kind.jsonPrimitive.content!="DOMAIN")assertEquals("66666666-6666-4666-8666-666666666666",control.getValue("txId").jsonPrimitive.content)
            }
            for((path,order) in manifest.getValue("jsonlOrder").jsonObject) {
                val bytes=Files.readAllBytes(f.root.resolve(path))
                assertFalse(bytes.contains(13.toByte()))
                assertTrue(bytes.isEmpty() || bytes.last()==10.toByte())
                val lines=bytes.toString(Charsets.UTF_8).split('\n').dropLast(1).filter{it.isNotEmpty()}
                assertEquals(order.jsonArray.map{it.jsonPrimitive.content},lines.map{Json.parseToJsonElement(it).jsonObject.getValue("storageId").jsonPrimitive.content})
            }
            val intent=Json.parseToJsonElement(Files.readString(f.root.resolve("$goldenBundle/intent.json"))).jsonObject
            assertEquals("INDEX_DOCUMENT",intent.getValue("operation").jsonPrimitive.content)
            assertEquals("golden_card",intent.getValue("cardId").jsonPrimitive.content)
            assertEquals("golden_doc",intent.getValue("documentId").jsonPrimitive.content)
            assertEquals(JsonNull,intent.getValue("expectedHead"))
            assertEquals(1,intent.getValue("next").jsonObject.getValue("revision").jsonPrimitive.int)
            assertEquals("documents/golden.md",intent.getValue("source").jsonObject.getValue("path").jsonPrimitive.content)
            val result=check(f,DesktopIndexInspectionCode.COMPLETED_STRUCTURE_ONLY)
            assertEquals(DesktopIndexObservedLive.EXPECTED_NEW,result.observedLive)
            assertTrue(result.missingProofs.containsAll(setOf(DesktopIndexMissingProof.ROOT_LINEAGE_AUTHORITY,DesktopIndexMissingProof.CONFIG_WRITER_AUTHORITY,DesktopIndexMissingProof.WRITER_HANDOFF,DesktopIndexMissingProof.READINESS_CACHE_EPOCH)))
            assertGoldenBytes(f)
        }
    }
    @Test fun `independent golden single original byte mutation refuses frozen evidence`()=runBlocking<Unit> {
        DesktopDocumentIndexTransactionSyntheticFixture().use{f->
            installGolden(f)
            val path=f.root.resolve("$goldenBundle/stage/vectors/golden_vector_01.json")
            val raw=Files.readAllBytes(path);val at=raw.indexOf('A'.code.toByte());assertTrue(at>=0)
            raw[at]='B'.code.toByte();Files.write(path,raw)
            assertFailsWith<AssertionError>{assertGoldenBytes(f)}
            check(f,DesktopIndexInspectionCode.CORRUPT)
        }
    }
    @Test fun `independent golden legal JSON whitespace cannot reuse frozen byte hash`()=runBlocking<Unit> {
        DesktopDocumentIndexTransactionSyntheticFixture().use{f->
            installGolden(f)
            val path=f.root.resolve("$goldenBundle/stage/card.json")
            val before=Files.readAllBytes(path);val after=before+32.toByte()
            assertEquals(Json.parseToJsonElement(before.toString(Charsets.UTF_8)),Json.parseToJsonElement(after.toString(Charsets.UTF_8)))
            Files.write(path,after)
            assertFailsWith<AssertionError>{assertGoldenBytes(f)}
            check(f,DesktopIndexInspectionCode.CORRUPT)
        }
    }
    private suspend fun check(f:DesktopDocumentIndexTransactionSyntheticFixture,code:DesktopIndexInspectionCode,
        inspector:DesktopDocumentIndexTransactionInspector=DesktopDocumentIndexTransactionInspector()):DesktopIndexInspectionResult {
        val before=f.snapshot();val result=inspector.inspect(f.root);val after=f.snapshot()
        assertEquals(before,after,"Inspector must not write synthetic data")
        assertEquals(DesktopIndexBusinessAdmission.BLOCKED,result.businessAdmission)
        assertEquals(code,result.code,result.toString())
        record(code.name,before,after,result)
        return result
    }
